Here is the commit message:
netfilter: nft_meta_bridge: fix stale stack leak via
 IIFHWADDR register

NFT_META_BRI_IIFHWADDR declares its destination register with
len = ETH_ALEN (6 bytes), which the register-init tracking rounds up to
two 32-bit registers (8 bytes). nft_meta_bridge_get_eval() then does
memcpy(dest, br_dev->dev_addr, ETH_ALEN), writing only 6 bytes and
leaving the upper 2 bytes of the second register as uninitialised
nft_do_chain() stack. A downstream load of that register span leaks
those stale bytes to userspace.

Zero the second register before the memcpy so the full declared span is
written.

Fixes: cbd2257dc96e ("netfilter: nft_meta_bridge: introduce NFT_META_BRI_IIFHWADDR support")
Cc: stable@vger.kernel.org
Signed-off-by: Davide Ornaghi <d.ornaghi97@gmail.com>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The `NFT_META_BRI_IIFHWADDR` expression declares its destination register with a length of `ETH_ALEN` (6 bytes), which the register-init tracking rounds up to 8 bytes (two 32-bit registers). However, `nft_meta_bridge_get_eval()` performs `memcpy(dest, br_dev->dev_addr, ETH_ALEN)` writing only 6 bytes, leaving the upper 2 bytes of the second register uninitialised from the `nft_do_chain()` stack. This results in a stale stack data leak when the full register span is subsequently read.

Here is the patch:

 static void nft_meta_bridge_get_eval(const struct nft_expr *expr,
 				     struct nft_regs *regs,
 				     const struct nft_pktinfo *pkt)
 {
 	const struct nft_meta *priv = nft_expr_priv(expr);
 	const struct net_device *in = nft_in(pkt), *out = nft_out(pkt);
 	u32 *dest = &regs->data[priv->dreg];
 	const struct net_device *br_dev;

 	switch (priv->key) {
 	case NFT_META_BRI_IIFNAME:
 		br_dev = nft_meta_get_bridge(in);
 		break;
 	case NFT_META_BRI_OIFNAME:
 		br_dev = nft_meta_get_bridge(out);
 		break;
 	case NFT_META_BRI_IIFPVID: {
 		u16 p_pvid;

 		br_dev = nft_meta_get_bridge(in);
 		if (!br_dev || !br_vlan_enabled(br_dev))
 			goto err;

 		br_vlan_get_pvid_rcu(in, &p_pvid);
 		nft_reg_store16(dest, p_pvid);
 		return;
 	}
 	case NFT_META_BRI_IIFVPROTO: {
 		u16 p_proto;

 		br_dev = nft_meta_get_bridge(in);
 		if (!br_dev || !br_vlan_enabled(br_dev))
 			goto err;

 		br_vlan_get_proto(br_dev, &p_proto);
 		nft_reg_store_be16(dest, htons(p_proto));
 		return;
 	}
 	case NFT_META_BRI_IIFHWADDR:
 		br_dev = nft_meta_get_bridge(in);
 		if (!br_dev)
 			goto err;

+		/* ETH_ALEN (6) is shorter than the destination register span (8) */
+		dest[1] = 0;
 		memcpy(dest, br_dev->dev_addr, ETH_ALEN);
 		return;
 	default:
 		return nft_meta_get_eval(expr, regs, pkt);
 	}

 	strscpy_pad((char *)dest, br_dev ? br_dev->name : "", IFNAMSIZ);
 	return;
 err:
 	regs->verdict.code = NFT_BREAK;
 }



